@layer moduix.components {
  .root,
  .legend,
  .helperText,
  .errorText {
    box-sizing: border-box;
  }

  .root {
    display: flex;
    flex-direction: column;
    gap: var(--moduix-fieldset-gap, var(--moduix-spacing-4));
    width: var(--moduix-fieldset-width, 100%);
    max-width: var(--moduix-fieldset-max-width, none);
    margin: var(--moduix-fieldset-margin, 0);
    padding: var(--moduix-fieldset-padding, 0);
    border-width: var(--moduix-fieldset-border-width, 0);
    border-style: var(--moduix-fieldset-border-style, solid);
    border-color: var(--moduix-fieldset-border-color, transparent);
    border-radius: var(--moduix-fieldset-radius, var(--moduix-radius-none));
    min-inline-size: 0;

    &[data-disabled] {
      opacity: var(--moduix-fieldset-disabled-opacity, var(--moduix-opacity-disabled));
    }

    &[data-invalid] {
      border-color: var(--moduix-fieldset-border-color-invalid, var(--moduix-color-destructive));
    }
  }

  .legend {
    display: inline-block;
    max-inline-size: 100%;
    overflow-wrap: anywhere;
    margin: var(--moduix-fieldset-legend-margin, 0);
    padding: var(--moduix-fieldset-legend-padding, 0 0 var(--moduix-spacing-3));
    color: var(--moduix-fieldset-legend-color, var(--moduix-color-foreground));
    font-size: var(--moduix-fieldset-legend-font-size, var(--moduix-text-lg));
    font-weight: var(--moduix-fieldset-legend-font-weight, var(--moduix-weight-semibold));
    line-height: var(--moduix-fieldset-legend-line-height, var(--moduix-line-height-text-lg));
  }

  .helperText,
  .errorText {
    overflow-wrap: anywhere;
    font-size: var(--moduix-fieldset-message-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-fieldset-message-line-height, var(--moduix-line-height-text-sm));
  }

  .helperText {
    color: var(--moduix-fieldset-helper-text-color, var(--moduix-color-muted-foreground));
  }

  .errorText {
    color: var(--moduix-fieldset-error-text-color, var(--moduix-color-destructive));
    font-weight: var(--moduix-fieldset-error-text-font-weight, var(--moduix-weight-medium));
  }
}

import { FieldsetContext, useFieldset, useFieldsetContext } from '@ark-ui/vue/fieldset';
import Fieldset from './Fieldset.vue';
import FieldsetErrorText from './FieldsetErrorText.vue';
import FieldsetHelperText from './FieldsetHelperText.vue';
import FieldsetLegend from './FieldsetLegend.vue';
import FieldsetRootProvider from './FieldsetRootProvider.vue';

export {
  Fieldset,
  FieldsetContext,
  FieldsetErrorText,
  FieldsetHelperText,
  FieldsetLegend,
  FieldsetRootProvider,
  useFieldset,
  useFieldsetContext,
};

export type {
  FieldsetContextProps,
  FieldsetErrorTextProps,
  FieldsetHelperTextProps,
  FieldsetLegendProps,
  FieldsetRootProps,
  FieldsetRootProviderProps,
  UseFieldsetContext,
  UseFieldsetProps,
  UseFieldsetReturn,
} from '@ark-ui/vue/fieldset';
